import{v2 as cloudinary}from"cloudinary";import bannerModel from"../models/bannerModel.js";const addBanner=async(req,res)=>{try{const{title:title,subtitle:subtitle,linkUrl:linkUrl,active:active,order:order,startDate:startDate,endDate:endDate,location:location}=req.body,imageDesktop=req.files?.imageDesktop?.[0],imageMobile=req.files?.imageMobile?.[0];if(!imageDesktop)return res.status(400).json({success:!1,message:"Image desktop is required"});const desktopUrl=await cloudinary.uploader.upload(imageDesktop.path,{resource_type:"image"}).then((res=>res.secure_url));let mobileUrl="";imageMobile&&(mobileUrl=await cloudinary.uploader.upload(imageMobile.path,{resource_type:"image"}).then((res=>res.secure_url)));const banner=new bannerModel({title:title,subtitle:subtitle,imageDesktop:desktopUrl,imageMobile:mobileUrl,linkUrl:linkUrl,active:"true"===active,order:Number(order)||0,startDate:startDate||null,endDate:endDate||null,location:location||"home_main",date:Date.now()});await banner.save(),res.json({success:!0,message:"Banner created successfully"})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},listBanners=async(req,res)=>{try{const banners=await bannerModel.find({});res.json({success:!0,banners:banners})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},removeBanner=async(req,res)=>{try{const{id:id}=req.body;if(!await bannerModel.findById(id))return res.status(404).json({success:!1,message:"Banner not found"});await bannerModel.findByIdAndDelete(id),res.json({success:!0,message:"Banner removed successfully"})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},singleBanner=async(req,res)=>{try{const{id:id}=req.params,banner=await bannerModel.findById(id);if(!banner)return res.status(404).json({success:!1,message:"Banner not found"});res.json({success:!0,banner:banner})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}},updateBanner=async(req,res)=>{try{const{title:title,subtitle:subtitle,linkUrl:linkUrl,active:active,order:order,startDate:startDate,endDate:endDate,location:location}=req.body,{id:id}=req.params,banner=await bannerModel.findById(id);if(!banner)return res.status(404).json({success:!1,message:"Banner not found"});const imageDesktop=req.files?.imageDesktop?.[0],imageMobile=req.files?.imageMobile?.[0];if(banner.title=title,banner.subtitle=subtitle,banner.linkUrl=linkUrl,banner.active="true"===active,banner.order=Number(order)||0,banner.startDate=startDate||null,banner.endDate=endDate||null,banner.location=location||"home_main",imageDesktop){const desktopUrl=await cloudinary.uploader.upload(imageDesktop.path,{resource_type:"image"}).then((res=>res.secure_url));banner.imageDesktop=desktopUrl}if(imageMobile){const mobileUrl=await cloudinary.uploader.upload(imageMobile.path,{resource_type:"image"}).then((res=>res.secure_url));banner.imageMobile=mobileUrl}await banner.save(),res.json({success:!0,message:"Banner updated successfully"})}catch(error){console.error(error),res.status(500).json({success:!1,message:error.message})}};export{addBanner,listBanners,removeBanner,singleBanner,updateBanner};